using UnityEngine;

namespace FlappyDragon.Game
{
    /// <summary>
    /// Every material and sound the game uses. The asset is generated by the editor
    /// ProjectBuilder; the models themselves are built in code from these materials.
    /// </summary>
    [CreateAssetMenu(menuName = "Flappy Dragon/Game Art")]
    public sealed class GameArt : ScriptableObject
    {
        [Header("Dragon")]
        public Material DragonScales;
        public Material DragonBelly;
        public Material DragonWing;
        public Material DragonHorn;
        public Material EyeWhite;
        public Material EyeDark;

        [Header("World")]
        public Material Rock;
        public Material RockDark;
        public Material Grass;
        public Material Dirt;
        public Material HillNear;
        public Material MountainFar;
        public Material Snow;
        public Material Cloud;

        [Header("Pickups and enemies")]
        public Material CoinBronze;
        public Material CoinSilver;
        public Material CoinGold;
        public Material Bat;
        public Material BatWing;
        public Material Fire;

        [Header("Particles")]
        public Material ParticleAdditive;
        public Material ParticleAlpha;

        [Header("Audio")]
        public AudioClip Flap;
        public AudioClip Point;
        public AudioClip Coin;
        public AudioClip Hit;
        public AudioClip Fall;
        public AudioClip Fireball;
        public AudioClip Burst;
        public AudioClip Medal;
        public AudioClip Click;
        public AudioClip Music;
    }
}
